import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"CI/CD with GitHub Actions","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/github-actions.md","filePath":"deployment/github-actions.md"}`),a={name:`deployment/github-actions.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="ci-cd-with-github-actions" tabindex="-1">CI/CD with GitHub Actions <a class="header-anchor" href="#ci-cd-with-github-actions" aria-label="Permalink to &quot;CI/CD with GitHub Actions&quot;">​</a></h1><p>TechyNews uses GitHub Actions for continuous integration and deployment. The pipeline is designed to ensure that only tested, verified code reaches the production server.</p><h2 id="deployment-workflow-deploy-yml" tabindex="-1">Deployment Workflow (<code>deploy.yml</code>) <a class="header-anchor" href="#deployment-workflow-deploy-yml" aria-label="Permalink to &quot;Deployment Workflow (`deploy.yml`)&quot;">​</a></h2><p>The primary workflow is triggered on pushes to the <code>main</code> branch. It consists of a single optimized job that builds, tests, and deploys the application:</p><ol><li><strong>Security Audit:</strong> Scans the codebase for hardcoded secrets before proceeding.</li><li><strong>Setup Environment:</strong> Sets up PHP 8.3 and Node.js 22, matching the production environment.</li><li><strong>Install &amp; Build:</strong> Uses GitHub Actions caching for both Composer and NPM. Runs <code>composer install</code> and <code>npm run build</code>.</li><li><strong>Prepare Test Environment:</strong> Sets up a lightning-fast local testing environment using SQLite (<code>database/database.sqlite</code>).</li><li><strong>E2E Smoke Tests:</strong> Starts the built application via <code>php artisan serve</code> and runs Cypress E2E tests (<code>cypress/e2e/smoke.cy.js</code>) against it.</li><li><strong>Package Release:</strong> Only if all tests pass, the action zips the essential production files (excluding <code>node_modules</code>, test databases, and logs) into <code>deploy.zip</code>.</li><li><strong>Deploy via Secure Webhook:</strong> The ZIP file is sent via an HTTPS POST request to the production server webhook (<code>https://techynews.lat/_m/ci-cd</code>). The webhook handles extracting the ZIP and deploying the update.</li><li><strong>Health &amp; Asset Integrity Checks:</strong> After deployment, the pipeline curls several critical URLs to ensure they return HTTP 200, and verifies that the critical JS chunks referenced in <code>manifest.json</code> were actually uploaded.</li><li><strong>Auto-Rollback:</strong> If any step fails during or after the deployment process, the action triggers a rollback webhook (<code>https://techynews.lat/_m/rollback</code>) to restore the previous working version.</li></ol><h2 id="secrets-management" tabindex="-1">Secrets Management <a class="header-anchor" href="#secrets-management" aria-label="Permalink to &quot;Secrets Management&quot;">​</a></h2><p>The deployment action requires the following GitHub repository secrets:</p><ul><li><code>TECHY_DEPLOY_TOKEN</code>: The secure token used to authenticate the webhook POST request on the production server.</li></ul><h2 id="rollbacks" tabindex="-1">Rollbacks <a class="header-anchor" href="#rollbacks" aria-label="Permalink to &quot;Rollbacks&quot;">​</a></h2><p>The pipeline includes an automatic fallback mechanism. If the deployment webhook or subsequent health checks fail, it automatically sends a rollback command to the server. You can also trigger this manually if needed, or push a git revert to the <code>main</code> branch.</p>',10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};